mapper.select:
SELECT * FROM ( SELECT R.*, C.ChnlName FROM shopion.tPrdProdReview R INNER JOIN shopion.tStrChnl C ON C.ChnlCode = R.ChnlCode
) T_REVIEW
ORDER BY ${sidx} ${sord} ORDER BY RegistDate DESC

SELECT R.*, C.ChnlName
FROM shopion.tPrdProdReview R
INNER JOIN shopion.tStrChnl C ON C.ChnlCode = R.ChnlCode

    AND R.ChnlCode = #{pChnlCode}

        AND R.ProdCode = 'cashluxury'

            AND (R.ProdCode != 'cashluxury'
            AND R.ProdCode = #{pProdCode}
            )



ORDER BY ((R.ProdGrade + R.DeliGrade + R.QualtyGrade + R.PriceGrade + R.SvcGrade) / 5) DESC, R.RegistDate DESC
LIMIT 0, #{pCnt}

SELECT COUNT(*)
FROM shopion.tPrdProdReview

    AND ChnlCode = #{pChnlCode}
    AND ReviewNo = #{pReviewNo}
    AND ReviewTitle = #{pReviewTitle}
    AND ReviewCntnts = #{pReviewCntnts}

        AND ProdCode = 'cashluxury'

            AND (ProdCode != 'cashluxury'
            AND ProdCode = #{pProdCode}
            )


    AND CustId = #{pCustId}
    AND RegistName LIKE CONCAT('%',#{pRegistName},'%')
    AND BrandName = #{pBrandName}

         AND RegistDate >= DATE_FORMAT(#{pStartDate}, '%Y%m%d') AND RegistDate < ADDDATE(DATE_FORMAT(#{pEndDate}, '%Y%m%d'), INTERVAL 1 DAY)

SELECT * FROM (
    SELECT R.*, C.ChnlName
    FROM shopion.tPrdProdReview R
    INNER JOIN shopion.tStrChnl C ON C.ChnlCode = R.ChnlCode



) T_REVIEW

    ORDER BY ${sidx} ${sord}
    ORDER BY RegistDate DESC

LIMIT #{topCnt}, #{countPerPage}
